"""Main-thread gesture controller. All camera inference stays on this computer."""
import math
import time
import json
import os
from pathlib import Path
import subprocess
_state={'tracked':0.,'stillness':0.,'burst':0.,'hue':0.,'growth':0.,'motion':0.,
        'left_x':.35,'left_y':.5,'right_x':.65,'right_y':.5,'left_valid':0.,'right_valid':0.,
        'ls_x':.4,'ls_y':.6,'le_x':.35,'le_y':.5,'rs_x':.6,'rs_y':.6,'re_x':.65,'re_y':.5,
        'center_x':.5,'center_y':.55}
_prev={}
_filtered={}
_worker=None
_worker_log=None
_last=0.
_status_time=0.

def value(key,default=0.):
    return _state.get(key,default)

def advance(points,dt,sensitivity=1.0,bloom_time=3.0):
    global _prev,_filtered
    dt=max(.005,min(.15,dt))
    blend=1.-math.exp(-dt*8.)
    _filtered={joint:tuple(old+(new-old)*blend for old,new in zip(_filtered.get(joint,p),p)) for joint,p in points.items()}
    points=dict(_filtered)
    tracked=bool(points.get('shoulder_l') or points.get('shoulder_r'))
    speeds={}
    for joint,point in points.items():
        if joint in _prev:
            speeds[joint]=min(3.,math.dist(point,_prev[joint])/dt)
    _prev=dict(points)
    wrist_speed=max(speeds.get('wrist_l',0.),speeds.get('wrist_r',0.))
    motion=max([speeds.get(j,0.) for j in ['wrist_l','wrist_r','elbow_l','elbow_r','shoulder_l','shoulder_r']]+[0.])
    signal=max(0.,min(1.,(wrist_speed-.18)*sensitivity*1.4)) if tracked else 0.
    _state['burst']=max(_state['burst']*math.exp(-dt*2.5),signal)
    _state['motion']+=(min(1.,motion)-_state['motion'])*(1.-math.exp(-dt*8.))
    if tracked and motion < .12/max(.25,sensitivity):
        _state['stillness']=min(1.,_state['stillness']+dt/max(.5,bloom_time))
    else:
        _state['stillness']=max(0.,_state['stillness']-dt*1.5)
    _state['tracked']=1. if tracked else 0.
    _state['growth']=min(1.,_state['growth']+dt/4.) if tracked else max(0.,_state['growth']-dt)
    for side,prefix in [('l','left'),('r','right')]:
        wrist=points.get('wrist_'+side)
        _state[prefix+'_valid']=1. if wrist else 0.
        _state[prefix+'_arm_valid']=1. if wrist and 'elbow_'+side in points and 'shoulder_'+side in points else 0.
        if wrist:
            for axis,val in zip(['x','y'],wrist):
                key=prefix+'_'+axis
                _state[key]+=(val-_state[key])*(1.-math.exp(-dt*12.))
        for joint,key in [('shoulder_',side+'s'),('elbow_',side+'e')]:
            point=points.get(joint+side)
            if point:
                for axis,val in zip(['x','y'],point):
                    k=key+'_'+axis
                    _state[k]+=(val-_state[k])*(1.-math.exp(-dt*12.))
    wrists=[p for j,p in points.items() if j.startswith('wrist_')]
    target_hue=(sum(p[1] for p in wrists)/len(wrists)-.5)*.65 if wrists else 0.
    _state['hue']+=(target_hue-_state['hue'])*(1.-math.exp(-dt*3.))
    shoulders=[p for j,p in points.items() if j.startswith('shoulder_')]
    if shoulders:
        _state['center_x']=sum(p[0] for p in shoulders)/len(shoulders)
        _state['center_y']=sum(p[1] for p in shoulders)/len(shoulders)+.08
    return dict(_state)

def read_points(chop):
    channels={ch.name.lower().replace(':','_').replace('/','_'):float(ch[0]) for ch in chop.chans()}
    points={}
    for joint in ['shoulder_l','shoulder_r','elbow_l','elbow_r','wrist_l','wrist_r']:
        stem,side=joint.rsplit('_',1)
        aliases=[joint,('left_' if side=='l' else 'right_')+stem,stem+('_left' if side=='l' else '_right')]
        values={}
        for name,v in channels.items():
            if not any(a in name for a in aliases):continue
            tail=name.rsplit('_',1)[-1]
            if tail in ['u','x','tx']:values['x']=v
            if tail in ['v','y','ty']:values['y']=v
            if tail in ['confidence','conf','c']:values['confidence']=v
        if 'x' in values and 'y' in values and values.get('confidence',1.)>=.25:
            x,y=values['x'],values['y']
            if -.15<x<1.15 and -.15<y<1.15:points[joint]=(x,y)
    return points

def tick():
    global _last,_status_time,_worker,_worker_log
    now=time.perf_counter()
    if _last and now-_last<1./15.:return
    dt=now-_last if _last else 1./30.
    _last=now
    comp=me.parent()
    root=Path(comp.fetch('asset_root', project.folder))
    runtime=root/'runtime_pose'
    runtime.mkdir(exist_ok=True)
    points={}
    fresh=False
    try:
        data=json.loads((runtime/'pose.json').read_text(encoding='utf-8'))
        fresh=time.time()-data['time']<1.5
        if fresh: points={j:tuple(p) for j,p in data['points'].items()}
    except (OSError,ValueError,KeyError): pass
    if not fresh and (_worker is None or _worker.poll() is not None):
        python=root/'.pose-venv/Scripts/python.exe'
        script=root/'pose_worker.py'
        if python.exists() and script.exists():
            if _worker_log: _worker_log.close()
            _worker_log=(runtime/'worker.log').open('ab')
            _worker=subprocess.Popen([str(python),str(script),'--root',str(root)],
                 stdin=subprocess.DEVNULL,stdout=_worker_log,stderr=_worker_log,
                 creationflags=getattr(subprocess,'CREATE_NO_WINDOW',0))
    source=comp.op('pose_input')
    if source is not None:
        temp=runtime/'frame.incoming.png'
        try:
            source.save(str(temp))
            os.replace(temp,runtime/'frame.png')
        except OSError: pass
    advance(points,dt,comp.par.Gesturesensitivity.eval(),comp.par.Stillbloomtime.eval())
    if now-_status_time>.25:
        table=comp.op('interaction_status')
        table.clear();table.appendRow(['signal','value'])
        for key in ['tracked','motion','burst','stillness','hue','growth','left_valid','right_valid']:
            table.appendRow([key,round(_state[key],3)])
        _status_time=now

// Stateful GPU trails: contour petals emit, drift, and fade in a feedback buffer.
uniform vec4 uSim; // absolute time, lifetime, drift speed, particle size in px
uniform vec4 uAmount; // particle amount
uniform vec4 uHands; // left wrist xy, right wrist xy
uniform vec4 uReact; // burst, left valid, right valid, enabled
out vec4 fragColor;
float hash21(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
float maskAt(vec2 uv){return texture(sTD2DInputs[1],uv).a;}
vec3 palette(float h){return mix(vec3(1.,.32,.48),vec3(1.,.82,.29),h);}
void main(){
 vec2 uv=vUV.st; vec2 res=uTD2DInfos[1].res.zw; vec2 px=1./res;
 float now=mod(uSim.x,10.);
 float then=texture(sTD2DInputs[0],vec2(.5)).a;
 float dt=clamp(mod(now-then+10.,10.),.004,.06);
 vec2 velocity=vec2(.013*sin(uv.y*12.+uSim.x*.7),.028)*uSim.z;
 for(int hand=0;hand<2;hand++){vec2 p=hand==0?uHands.xy:uHands.zw;float v=hand==0?uReact.y:uReact.z;vec2 d=uv-p;velocity+=normalize(d+vec2(.0001))*.14*uReact.x*v*exp(-length(d)*10.);}
 vec3 history=texture(sTD2DInputs[0],uv-velocity*dt).rgb;
 history*=exp(-dt*3./max(.15,uSim.y));
 vec2 grid=uv*res/24.; vec2 cell=floor(grid);
 vec3 emission=vec3(0.);
 for(int j=-1;j<=1;j++)for(int i=-1;i<=1;i++){
  vec2 id=cell+vec2(i,j); float h=hash21(id);
  float period=1.1+h*.9;
  float life=fract(uSim.x/period+h);
  vec2 center=(id+.5+vec2(hash21(id+3.),hash21(id+8.))*.45-.225)*24./res;
  float l=maskAt(center-vec2(12.*px.x,0.)); float r=maskAt(center+vec2(12.*px.x,0.));
  float b=maskAt(center-vec2(0.,12.*px.y)); float t=maskAt(center+vec2(0.,12.*px.y));
  float edge=clamp(max(max(l,r),max(b,t))-min(min(l,r),min(b,t)),0.,1.);
  vec2 outward=normalize(vec2(l-r,b-t)+vec2(.001,.002));
  vec2 drift=outward*life*.018*uSim.z+vec2(sin(life*6.+h*20.)*.008,life*.022)*uSim.z;
  drift*=1.+uReact.x*3.;
  vec2 q=(uv-center-drift)*res/max(1.,uSim.w);
  float spin=h*6.28+uSim.x*.8;
  q=mat2(cos(spin),-sin(spin),sin(spin),cos(spin))*q;
  float petal=exp(-dot(q*vec2(.65,1.8),q*vec2(.65,1.8))*2.2);
  float twinkle=.5+.5*sin(uSim.x*5.+h*25.);
  float emitGate=smoothstep(.08,.35,edge)*(1.-smoothstep(.5,.95,life));
  emitGate*=step(h,clamp(uAmount.x+uReact.x*.5,0.,1.));
  emission+=palette(h)*petal*emitGate*(.6+.4*twinkle)*1.4*(1.+uReact.x*2.);
 }
 for(int hand=0;hand<2;hand++)for(int k=0;k<12;k++){
  float h=hash21(vec2(k,hand+21.));float age=fract(uSim.x*(.5+h*.7)+h);
  vec2 wrist=hand==0?uHands.xy:uHands.zw;float valid=hand==0?uReact.y:uReact.z;
  float angle=h*6.28318+sin(uSim.x+h*10.)*.2;
  vec2 center=wrist+vec2(cos(angle),sin(angle))*(.006+age*.12*(1.+uReact.x));
  vec2 q=(uv-center)*res/max(1.,uSim.w*1.2);
  float petal=exp(-dot(q*vec2(.7,1.5),q*vec2(.7,1.5)));
  emission+=palette(h)*petal*valid*uReact.x*(1.-age)*2.;
 }
 vec3 particles=max(history,emission);
 fragColor=TDOutputSwizzle(vec4(particles,now));
}

// Procedural blossoms shaded by the live camera, clipped by the person matte.
uniform vec4 uSettings; // time, density, effect strength, brightness
uniform vec4 uLook; // background brightness, mirror, unused, unused
uniform vec4 uMotion; // amount, rotation speed, sway, bloom
uniform vec4 uReact; // stillness, burst, hue, tracked
out vec4 fragColor;
float hash21(vec2 p) { return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453123); }
vec3 palette(float h) {
    if(h<0.20) return vec3(1.0,0.30,0.48);
    if(h<0.40) return vec3(1.0,0.70,0.23);
    if(h<0.60) return vec3(0.83,0.48,1.0);
    if(h<0.80) return vec3(1.0,0.88,0.71);
    return vec3(1.0,0.49,0.25);
}
vec3 hueShift(vec3 c,float h){vec3 k=vec3(.57735027);float a=h*6.28318;return clamp(c*cos(a)+cross(k,c)*sin(a)+k*dot(k,c)*(1.-cos(a)),0.,1.);}
void main() {
    vec2 uv=vUV.st;
    if(uLook.y>0.5) uv.x=1.0-uv.x;
    vec3 camera=texture(sTD2DInputs[0],uv).rgb;
    float mask=texture(sTD2DInputs[1],uv).a;
    float aspect=uTD2DInfos[0].res.z/uTD2DInfos[0].res.w;
    vec2 gridSize=vec2(aspect,1.0)*uSettings.y;
    vec2 grid=uv*gridSize;
    vec2 cell=floor(grid);
    vec3 flowers=vec3(0.025,0.105,0.055);
    for(int y=-1;y<=1;y++) for(int x=-1;x<=1;x++) {
        vec2 id=cell+vec2(x,y);
        float h=hash21(id);
        vec2 jitter=vec2(hash21(id+13.2),hash21(id+49.7))-.5;
        float phase=uSettings.x*(.7+h*.8)+h*30.;
        vec2 center=id+.5+jitter*.56;
        center+=uMotion.x*uMotion.z*vec2(sin(phase),cos(phase*.73+h*12.));
        vec2 sampleUV=center/gridSize;
        vec3 shade=texture(sTD2DInputs[0],sampleUV).rgb;
        float lum=dot(shade,vec3(.2126,.7152,.0722));
        float person=texture(sTD2DInputs[1],sampleUV).a;
        vec2 q=grid-center;
        float direction=hash21(id+26.)>.5?1.:-1.;
        float turn=h*6.28318+uMotion.x*(uSettings.x*uMotion.y*(.35+.65*hash21(id+17.))*direction+.22*sin(phase*.6));
        q=mat2(cos(turn),-sin(turn),sin(turn),cos(turn))*q;
        float r=length(q);
        float a=atan(q.y,q.x);
        float petals=5.+floor(hash21(id+9.1)*5.);
        float growth=1.+uMotion.x*uMotion.w*sin(phase*.8);
        growth*=mix(1.,mix(.42,1.45,uReact.x),uReact.w);
        float radius=(.35+.075*cos(a*petals))*growth;
        float blossom=1.-smoothstep(radius-.035,radius+.015,r);
        blossom*=smoothstep(.12,.52,person);
        vec3 petal=hueShift(palette(h),uReact.z)*(.25+.95*sqrt(max(lum,0.)));
        petal*=.76+.24*cos(a*petals);
        petal+=.08*pow(max(0.,1.-r/.45),2.);
        flowers=mix(flowers,petal,blossom);
        float core=(1.-smoothstep(.065*growth,.12*growth,r))*smoothstep(.12,.52,person);
        vec3 gold=mix(vec3(.23,.10,.025),vec3(1.,.78,.18),.5+.5*sin(a*13.+r*180.));
        flowers=mix(flowers,gold*(.4+.6*sqrt(max(lum,0.))),core);
    }
    float matte=smoothstep(.18,.78,mask);
    vec3 personColor=mix(camera,flowers,clamp(uSettings.z,0.,1.));
    vec3 background=texture(sTD2DInputs[2],vUV.st).rgb*uLook.x;
    vec3 outputColor=mix(background,personColor,matte)*uSettings.w;
    fragColor=TDOutputSwizzle(vec4(outputColor,1.));
}

// Tracked arm vines and animated butterflies, drawn over the live flower scene.
uniform vec4 uGarden; // butterfly count, vines amount, mirror, seconds
uniform vec4 uBody; // body center x,y, tracking confidence, vine growth
uniform vec4 uLeftUpper; // shoulder xy, elbow xy
uniform vec4 uLeftLower; // wrist xy, valid, unused
uniform vec4 uRightUpper;
uniform vec4 uRightLower;
out vec4 fragColor;
float hash21(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
vec2 screenPoint(vec2 p){return vec2(uGarden.z>.5?1.-p.x:p.x,p.y);}
vec4 vine(vec2 p,vec2 a,vec2 b,float growth,float seed){
 vec2 ab=b-a; float len=length(ab); if(len<.01)return vec4(0.);
 vec2 axis=ab/len; vec2 normal=vec2(-axis.y,axis.x);
 float t=clamp(dot(p-a,axis)/len,0.,1.);
 float bend=sin(t*24.+seed+uGarden.w*.3)*.004;
 float distance=abs(dot(p-a,normal)-bend);
 float stem=(1.-smoothstep(.0014,.0035,distance))*step(t,growth)*step(0.,dot(p-a,axis))*step(dot(p-a,axis),len);
 vec3 color=vec3(.18,.54,.12); float alpha=stem;
 for(int j=0;j<8;j++){
  float along=(float(j)+.5)/8.; float side=mod(float(j),2.)*2.-1.;
  vec2 pos=a+ab*along+normal*sin(along*24.+seed+uGarden.w*.3)*.004;
  vec2 direction=normalize(axis*.55+normal*side);
  vec2 leafCenter=pos+direction*.011;
  vec2 q=p-leafCenter; float x=dot(q,direction)/.016;float y=dot(q,vec2(-direction.y,direction.x))/.006;
  float leaf=(1.-smoothstep(.8,1.,x*x+y*y))*smoothstep(along-.04,along+.04,growth);
  vec3 green=mix(vec3(.08,.28,.06),vec3(.4,.76,.18),clamp(.5+.5*y,0.,1.));
  if(leaf>alpha){color=green;alpha=leaf;}
 }
 return vec4(color,alpha);
}
vec4 butterfly(vec2 p,vec2 center,float angle,float phase,float scale,float hue){
 vec2 q=p-center; q=mat2(cos(angle),-sin(angle),sin(angle),cos(angle))*q;
 q/=scale;
 float flap=.2+.8*abs(sin(phase));
 q.x/=flap;
 float upper=pow((abs(q.x)-.48)/.48,2.)+pow((q.y-.20)/.52,2.);
 float lower=pow((abs(q.x)-.34)/.34,2.)+pow((q.y+.35)/.34,2.);
 float wing=min(upper,lower);
 float shape=1.-smoothstep(.85,1.05,wing);
 vec3 tone=mix(vec3(1.,.42,.06),vec3(.65,.3,1.),hue);
 tone*=.5+.5*(1.-clamp(wing,0.,1.));
 float spots=pow(abs(sin(q.y*16.+q.x*9.)),18.);
 tone=mix(tone,vec3(1.,.96,.7),spots*.6);
 tone=mix(tone,vec3(.045,.018,.025),smoothstep(.68,.98,wing));
 float body=1.-smoothstep(.065,.11,abs(q.x));body*=1.-smoothstep(.35,.5,abs(q.y));
 tone=mix(tone,vec3(.06,.025,.02),body);
 return vec4(tone,max(shape,body));
}
void main(){
 vec2 uv=vUV.st; vec3 scene=texture(sTD2DInputs[0],uv).rgb;
 float aspect=uTD2DInfos[0].res.z/uTD2DInfos[0].res.w;
 vec2 metric=vec2(aspect,1.);vec2 p=uv*metric;
 float growth=uBody.w;
 for(int side=0;side<2;side++){
  vec4 upper=side==0?uLeftUpper:uRightUpper; vec4 lower=side==0?uLeftLower:uRightLower;
  float enabled=uGarden.y*uBody.z*lower.z;
  vec2 a=screenPoint(upper.xy)*metric; vec2 b=screenPoint(upper.zw)*metric;vec2 d=screenPoint(lower.xy)*metric;
  vec4 v=vine(p,a,b,smoothstep(0.,.55,growth),float(side)*4.);
  scene=mix(scene,v.rgb,v.a*enabled);
  v=vine(p,b,d,smoothstep(.45,1.,growth),float(side)*4.+2.);
  scene=mix(scene,v.rgb,v.a*enabled);
 }
 vec2 center=screenPoint(uBody.xy);
 for(int i=0;i<12;i++){
  if(float(i)>=uGarden.x)break;
  float h=hash21(vec2(i,7.)); float time=uGarden.w*(.3+h*.15);
  float a=time+float(i)*2.39996;
  vec2 pos=center+vec2(cos(a)*(.20+.10*h)/aspect,sin(a*.83)*(.16+.12*h));
  pos+=vec2(sin(time*2.1+h*8.),cos(time*1.7+h*4.))*.025;
  float angle=sin(time+h*20.)*.7;
  vec4 b=butterfly(p,pos*metric,angle,uGarden.w*(7.+h*5.)+h*12.,.021+h*.011,h);
  scene=mix(scene,b.rgb,b.a);
 }
 fragColor=TDOutputSwizzle(vec4(scene,1.));
}

// Soft silhouette rim, warm bloom, and drifting petal trails over the scene.
uniform vec4 uEdge; // glow amount, particles amount, mirror camera, time
out vec4 fragColor;
void main(){
 vec2 uv=vUV.st; vec2 personUV=uv;
 if(uEdge.z>.5) personUV.x=1.-personUV.x;
 vec3 scene=texture(sTD2DInputs[0],uv).rgb;
 float hard=texture(sTD2DInputs[1],personUV).r;
 float soft=texture(sTD2DInputs[1],personUV).g;
 vec2 px=uTD2DInfos[0].res.xy*2.;
 vec3 smoothed=(scene*2.+texture(sTD2DInputs[0],uv+vec2(px.x,0)).rgb+texture(sTD2DInputs[0],uv-vec2(px.x,0)).rgb+texture(sTD2DInputs[0],uv+vec2(0,px.y)).rgb+texture(sTD2DInputs[0],uv-vec2(0,px.y)).rgb)/6.;
 scene=mix(scene,smoothed,clamp(abs(soft-hard)*2.,0.,.65));
 float halo=soft*(1.-smoothstep(.15,.9,hard))*3.;
 float inner=abs(soft-hard)*.5;
 vec3 tint=mix(vec3(1.,.35,.58),vec3(1.,.76,.28),.5+.5*sin(personUV.y*5.+uEdge.w*.45));
 vec3 glow=tint*(halo+inner)*uEdge.x;
 vec3 particles=texture(sTD2DInputs[2],personUV).rgb*uEdge.y;
 vec3 additions=glow+particles;
 vec3 color=1.-(1.-clamp(scene,0.,1.))*exp(-additions);
 fragColor=TDOutputSwizzle(vec4(color,1.));
}

